import fs from 'fs';

import { resolveGlobalConfigDir, resolveGlobalConfigPath, resolveLocalEnvPath } from './paths.js';

const API_KEY_NAME = 'OPENAI_API_KEY';

// Matches `[export ]OPENAI_API_KEY=<rest>`; commented-out lines never match.
const ENV_DEFINITION_PATTERN = new RegExp(`^(\\s*(?:export\\s+)?${API_KEY_NAME}\\s*=[ \\t]*)(.*)$`);

const ensureDir = (dirPath) => {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true, mode: 0o700 });
  }
};

const sanitizeValue = (value) => {
  if (typeof value !== 'string') return null;
  const sanitized = value.trim().replace(/^['"]|['"]$/g, '').trim();
  return sanitized || null;
};

const assertValidKey = (key) => {
  if (!key) throw new Error('API key is required');
  if (/[\r\n]/.test(key)) throw new Error('API key must not contain line breaks');
};

/**
 * Splits the raw text after `=` into the value and the surrounding bytes, so a
 * definition can be rewritten without touching its quotes or trailing comment.
 */
const parseEnvValue = (raw) => {
  const quote = raw[0];
  if (quote === '"' || quote === "'") {
    const body = quote === '"' ? /^"((?:\\.|[^"\\])*)"/.exec(raw) : /^'([^']*)'/.exec(raw);
    if (body) {
      const suffix = raw.slice(body[0].length);
      if (/^\s*(#.*)?$/.test(suffix)) {
        const value = quote === '"' ? body[1].replace(/\\(["\\])/g, '$1') : body[1];
        return { value, quote, suffix };
      }
    }
  }

  const commentStart = raw.search(/(^|\s)#/);
  const valuePart = commentStart === -1 ? raw : raw.slice(0, commentStart);
  const value = valuePart.trimEnd();
  return { value, quote: '', suffix: raw.slice(value.length) };
};

const splitLines = (content) => {
  const lines = content.split('\n');
  return lines.map((line, index) => {
    const hasCarriageReturn = line.endsWith('\r') && index < lines.length - 1;
    return {
      text: hasCarriageReturn ? line.slice(0, -1) : line,
      eol: index < lines.length - 1 ? (hasCarriageReturn ? '\r\n' : '\n') : ''
    };
  });
};

const findLastDefinition = (lines) => {
  for (let index = lines.length - 1; index >= 0; index -= 1) {
    const match = ENV_DEFINITION_PATTERN.exec(lines[index].text);
    if (match) {
      return { index, prefix: match[1], ...parseEnvValue(match[2]) };
    }
  }
  return null;
};

const formatEnvValue = (key, preferredQuote) => {
  const needsDoubleQuotes =
    (preferredQuote === '' && /^['"]|\s|#/.test(key)) || (preferredQuote === "'" && key.includes("'"));
  const quote = needsDoubleQuotes ? '"' : preferredQuote;
  if (quote === '"') return `"${key.replace(/(["\\])/g, '\\$1')}"`;
  if (quote === "'") return `'${key}'`;
  return key;
};

const readJsonConfig = (configPath) => {
  const content = fs.readFileSync(configPath, 'utf8');
  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (error) {
    throw new Error(`Global config at ${configPath} is not valid JSON: ${error.message}`);
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error(`Global config at ${configPath} must contain a JSON object`);
  }
  return parsed;
};

export const hasLocalApiKey = (cwd = process.cwd()) => Boolean(getLocalApiKey(cwd));

export const getLocalApiKey = (cwd = process.cwd()) => {
  const envPath = resolveLocalEnvPath(cwd);
  if (!fs.existsSync(envPath)) return null;
  const content = fs.readFileSync(envPath, 'utf8');
  const definition = findLastDefinition(splitLines(content));
  if (!definition) return null;
  return definition.value.trim() || null;
};

export const setLocalApiKey = (key, cwd = process.cwd()) => {
  assertValidKey(key);
  const envPath = resolveLocalEnvPath(cwd);
  const content = fs.existsSync(envPath) ? fs.readFileSync(envPath, 'utf8') : '';
  const lines = splitLines(content);
  const definition = findLastDefinition(lines);

  let nextContent;
  if (definition) {
    const line = lines[definition.index];
    line.text = `${definition.prefix}${formatEnvValue(key, definition.quote)}${definition.suffix}`;
    nextContent = lines.map(({ text, eol }) => `${text}${eol}`).join('');
  } else {
    const eol = content.includes('\r\n') ? '\r\n' : '\n';
    const separator = content && !content.endsWith('\n') ? eol : '';
    nextContent = `${content}${separator}${API_KEY_NAME}=${formatEnvValue(key, '')}${eol}`;
  }

  fs.writeFileSync(envPath, nextContent, { encoding: 'utf8', mode: 0o600 });
  return envPath;
};

export const hasGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) =>
  Boolean(getGlobalApiKey(homeDir));

export const getGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) => {
  const configPath = resolveGlobalConfigPath(homeDir);
  if (!fs.existsSync(configPath)) return null;
  const content = fs.readFileSync(configPath, 'utf8');
  try {
    const parsed = JSON.parse(content);
    return sanitizeValue(parsed?.[API_KEY_NAME]);
  } catch (error) {
    return null;
  }
};

export const setGlobalApiKey = (key, homeDir = process.env.HOME || process.env.USERPROFILE) => {
  assertValidKey(key);
  const configPath = resolveGlobalConfigPath(homeDir);
  const existing = fs.existsSync(configPath) ? readJsonConfig(configPath) : {};
  ensureDir(resolveGlobalConfigDir(homeDir));
  const payload = JSON.stringify({ ...existing, [API_KEY_NAME]: key }, null, 2);
  fs.writeFileSync(configPath, payload, { encoding: 'utf8', mode: 0o600 });
  return configPath;
};

