import fs from 'fs';
import os from 'os';
import path from 'path';
import { spawnSync } from 'child_process';
import { it } from 'vitest';

const CLI = path.resolve('dist/index.js');
const AGENT_ENV = path.resolve('../frai-agent/dist/config/env.js');

it('e2e', async () => {
  const w = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-e2e-'));
  const home = path.join(w, 'home');
  const proj = path.join(w, 'proj');
  const cfg = path.join(home, '.config/frai/config');
  fs.mkdirSync(path.dirname(cfg), { recursive: true });
  fs.mkdirSync(proj);
  const env = { ...process.env, HOME: home };
  delete env.OPENAI_API_KEY;
  const run = (...args) => {
    const r = spawnSync(process.execPath, [CLI, ...args], { cwd: proj, env, input: '', encoding: 'utf8', timeout: 10000 });
    return `exit=${r.status} ${(r.stdout + r.stderr).replace(/\[[^\]]+Z\] /g, '').trim()}`;
  };
  const out = [];
  const envFile = path.join(proj, '.env');

  fs.writeFileSync(envFile, '# settings\n\nDB=postgres://x\n');
  out.push('== config, .env without key', run('config'));
  out.push('== setup --key', run('setup', '--key', 'sk-local'), JSON.stringify(fs.readFileSync(envFile, 'utf8')));
  out.push('== config after', run('config'));

  fs.writeFileSync(cfg, '{\n  "theme": "dark"\n}');
  out.push('== setup --key --global', run('setup', '--key', 'sk-global', '--global'), fs.readFileSync(cfg, 'utf8'));

  fs.writeFileSync(cfg, '{ broken');
  out.push('== invalid json', run('setup', '--key', 'sk-x', '--global'), fs.readFileSync(cfg, 'utf8'));

  fs.writeFileSync(cfg, '{"theme":"dark"}');
  out.push('== legacy local', run('--setup', '--key', 'sk-legacy'), JSON.stringify(fs.readFileSync(envFile, 'utf8')));
  out.push('== legacy global', run('--setup', '--key', 'sk-legacy-global', '--global'), fs.readFileSync(cfg, 'utf8'));

  fs.writeFileSync(envFile, 'A=1\nexport OPENAI_API_KEY="sk-exported" # rotated\n');
  const agent = spawnSync(
    process.execPath,
    ['--input-type=module', '-e', `import(${JSON.stringify(AGENT_ENV)}).then(m => console.log('agent key:', m.resolveOpenAiApiKey()))`],
    { cwd: proj, env, encoding: 'utf8' }
  );
  out.push('== agent', agent.stdout + agent.stderr);
  out.push('== rotate', run('setup', '--key', 'sk-rotated'), JSON.stringify(fs.readFileSync(envFile, 'utf8')));

  console.log(out.join('\n'));
  fs.rmSync(w, { recursive: true, force: true });
}, 60000);

