  out.push('== legacy global', run('--setup', '--key', 'sk-legacy-global', '--global'), fs.readFileSync(cfg, 'utf8'));

  fs.writeFileSync(envFile, 'A=1\nexport OPENAI_API_KEY="sk-exported" # rotated\n');
  const agent = spawnSync(
    process.execPath,
    ['--input-type=module', '-e', `import(${JSON.stringify(AGENT_ENV)}).then(m => console.log('agent key:', m.resolveOpenAiApiKey()))`],
    { cwd: proj, env, encoding: 'utf8' }
  );
  out.push('== agent', agent.stdout + agent.stderr);
  out.push('== rotate', run('setup', '--key', 'sk-rotated'), JSON.stringify(fs.readFileSync(envFile, 'utf8')));

  console.log(out.join('\n'));
  fs.rmSync(w, { recursive: true, force: true });
}, 60000);

